<?php
if(!defined('ABSPATH')){exit;} final class DSVS_Parser { private static function xpath($html){if(!class_exists('DOMDocument')){return false;}$doc=new DOMDocument();$old=libxml_use_internal_errors(true);$ok=$doc->loadHTML('<?xml encoding="UTF-8">'.$html);libxml_clear_errors();libxml_use_internal_errors($old);return $ok?new DOMXPath($doc):false;} private static function clean($text){return trim(preg_replace('/\s+/u',' ',$text));} private static function cells($xpath,$row){$cells=array();foreach($xpath->query('./th|./td',$row) as $cell){$value=self::clean($cell->textContent);if(''!==$value){$cells[]=$value;}}return $cells;} public static function get_standings($html){$xpath=self::xpath($html);if(!$xpath){return array();}foreach($xpath->query('//table') as $table){$text=self::clean($table->textContent);if(false===stripos($text,'Mannschaft')||false===stripos($text,'Partien')){continue;}$rows=array();foreach($xpath->query('.//tr',$table) as $row){$cells=self::cells($xpath,$row);if(count($cells)>=9&&ctype_digit($cells[0])){$rows[]=array_slice($cells,0,9);}}if($rows){return $rows;}}return array();} public static function get_current_games($html){return self::games($html,true);} public static function get_schedule($html){$games=self::games($html,false);usort($games,function($a,$b){return $a['timestamp']<=>$b['timestamp'];});return $games;} private static function games($html,$current_only){$xpath=self::xpath($html);if(!$xpath){return array();}$games=array();foreach($xpath->query('//table') as $table){$is_current=false!==stripos($table->textContent,'AKTUELLE ERGEBNISSE');if($current_only!==$is_current){continue;}foreach($xpath->query('.//tr',$table) as $row){$game=self::parse_game(self::cells($xpath,$row));if($game){$games[]=$game;}}}return $games;} private static function parse_game($cells){$date_index=false;foreach($cells as $index=>$cell){if(preg_match('/(\d{2}\.\d{2}\.\d{4}).*?(\d{2}:\d{2})/u',$cell,$match)){$date_index=$index;$date=$match[1];$time=$match[2];break;}}if(false===$date_index){return false;}$rest=array_slice($cells,$date_index+1);foreach($rest as $index=>$value){if(preg_match('/^(?:\d+\s*:\s*\d+|:)$/',$value)&&$index>=1&&isset($rest[$index+1])){$dt=DateTime::createFromFormat('!d.m.Y H:i',$date.' '.$time,wp_timezone());if(!$dt){return false;}return array('date'=>$date,'time'=>$time,'timestamp'=>$dt->getTimestamp(),'home'=>$rest[$index-1],'result'=>preg_replace('/\s+/','',$value),'away'=>$rest[$index+1]);}}return false;} public static function get_ranking($html){$xpath=self::xpath($html);if(!$xpath){return array();}foreach($xpath->query('//table') as $table){$table_text=self::clean($table->textContent);if(false===stripos($table_text,'RANGLISTE')||false===stripos($table_text,'RANG')||false===stripos($table_text,'QUOTE')){continue;}$ranking=array();foreach($xpath->query('.//tr',$table) as $row){$raw_cells=array();foreach($xpath->query('./th|./td',$row) as $cell){$raw_cells[]=$cell;}if(count($raw_cells)<4){continue;}$rank=self::clean($raw_cells[0]->textContent);if(!preg_match('/^\d+$/',$rank)){continue;}$last_index=count($raw_cells)-1;$quote=self::clean($raw_cells[$last_index]->textContent);if(false===strpos($quote,'%')){continue;}$numbers=array();for($i=$last_index-1;$i>=2&&count($numbers)<3;$i--){$value=self::clean($raw_cells[$i]->textContent);if(preg_match('/^\d+$/',$value)){array_unshift($numbers,$value);}}if(count($numbers)<3){continue;}$identity=self::parse_ranking_identity($xpath,$raw_cells[1]);$ranking[]=array('rank'=>$rank,'player'=>$identity['player'],'team'=>$identity['team'],'played'=>$numbers[0],'won'=>$numbers[1],'lost'=>$numbers[2],'quote'=>$quote);}if($ranking){return $ranking;}}return array();} private static function parse_ranking_identity($xpath,$cell){$lines=self::ranking_cell_lines($cell);if(count($lines)>=2){return array('player'=>$lines[0],'team'=>$lines[1]);}$full=self::clean($cell->textContent);foreach(DSVS_Settings::highlighted_teams() as $known_team){$position=mb_stripos($full,$known_team);if(false!==$position){$player=trim(mb_substr($full,0,$position));if(''!==$player){return array('player'=>$player,'team'=>$known_team);}}}return array('player'=>$full,'team'=>'');} private static function ranking_cell_lines($cell){$lines=array();$current='';foreach($cell->childNodes as $node){if(XML_ELEMENT_NODE===$node->nodeType&&'br'===strtolower($node->nodeName)){self::push_ranking_line($lines,$current);$current='';continue;}$text=self::clean($node->textContent);if(''===$text){continue;}if(XML_ELEMENT_NODE===$node->nodeType&&in_array(strtolower($node->nodeName),array('div','p','span','strong','b','a'),true)){self::push_ranking_line($lines,$current);$current='';self::push_ranking_line($lines,$text);}else{$current.=(''===$current?'':' ').$text;}}self::push_ranking_line($lines,$current);$lines=array_values(array_unique(array_filter($lines)));if(count($lines)>2){$numeric_tail=end($lines);if(preg_match('/^\d+$/',$numeric_tail)){array_pop($lines);}}return array_slice($lines,0,2);} private static function push_ranking_line(&$lines,$text){$text=self::clean($text);if(''!==$text&&!preg_match('/^\d+$/',$text)){$lines[]=$text;}} public static function get_upcoming_highlighted_games($games,$limit){$now=current_time('timestamp');$games=array_values(array_filter($games,function($game)use($now){return $game['timestamp']>=$now&&':'===$game['result']&&(DSVS_Settings::is_highlighted_team($game['home'])||DSVS_Settings::is_highlighted_team($game['away']));}));return array_slice($games,0,$limit);} }
